def shortest_path(graph, source, target):
    from collections import deque

    # Initialize distances to all nodes as infinity
    distances = {node: float("inf") for node in graph}
    distances[source] = 0

    # Initialize the queue for BFS
    queue = deque([source])

    while queue:
        current = queue.popleft()

        for neighbor, weight in graph.get(current, []):
            distance = distances[current] + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                queue.append(neighbor)

    # Get the shortest path from source to target
    target_distance = distances.get(target, float("inf"))
    if target_distance == float("inf"):
        return float("inf"), None
    else:
        path = [target]
        while path[-1] != source:
            for prev, weight in graph.get(path[-1], []):
                if distances[prev] + weight == distances[path[-1]]:
                    path.append(prev)
                    break
        path.reverse()
        return target_distance, path

