def shortest_path(graph, source, target):
    # Initialize distances to all nodes as infinity and add the source node with distance 0.
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    # Initialize the predecessor dictionary to track how the shortest path was reached.
    predecessors = {node: None for node in graph}

    # Priority queue to hold nodes to be checked, ordered by increasing distance.
    from queue import PriorityQueue
    pq = PriorityQueue()
    pq.put((0, source))

    while not pq.empty():
        # Pop the node with the smallest distance from the priority queue.
        current_distance, current_node = pq.get()

        # If this node is the target, we have found the shortest path.
        if current_node == target:
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = predecessors[current_node]
            return (current_distance, path[::-1])

        # If the distance to the current node is greater than the distance added in the previous iteration,
        # the graph is not a shortest path graph and we can stop.
        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            # If a shorter path is found to the neighbor, update the distance and the predecessor.
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                predecessors[neighbor] = current_node
                pq.put((distance, neighbor))

    # If the target is unreachable, return infinity and None.
    return (float("inf"), None)
